// hestia-nodeJS Unix Domain Socket wrapper
const fs = require('node:fs')
const process = require('node:process')
const http = require('node:http')

// Clean orphaned socket
try {
	const port = process.env.PORT
	const instance = process.env.NODE_APP_INSTANCE || 0

	if (typeof port !== 'string' || !/(\/hestia-nodeJS\/).+\-[0-9]+(.sock)$/.test(port))
		throw false

	if (/(-0.sock)$/.test(port) && instance > 0)
		process.env.PORT = port.substring(0, port.length - '0.sock'.length) + instance + '.sock'

 	if (fs.statSync(port)?.isSocket())
		fs.rmSync(port)
}
catch (e) {}

http._createServer = http.createServer

http.createServer = function (...args) {
	const ret = http._createServer(...args)

	ret.prependListener('listening', () => {
		try {
			// Adjust socket permission to allow writing for group www-data
			const port = ret.address()

			if (typeof port === 'string')
				fs.chmodSync(port, 0o770)
		}
		catch (e) {}
	})

	ret.prependListener('request', (req, res) => {
		req.ip = req.headers['x-forwarded-for'] || req.headers['x-real-ip'] || req.socket.remoteAddress
	})

	return ret
}

module.exports = http
